// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: ownerActor is the address that will be the initial owner (must be non-zero)
    // newOwner is the address to transfer ownership to (may be any address, but we will avoid zero to keep it meaningful)
    function testFuzz_property(address ownerActor, address newOwner) public {
        // keep addresses in wide admissible domain
        vm.assume(ownerActor != address(0));
        vm.assume(newOwner != address(0));

        // Make ownerActor the deployer/owner by impersonating it at contract construction time is not possible here
        // because c was constructed in setUp() by this test contract. So we must make ownerActor the current owner by
        // having the test contract (which deployed c) transfer ownership to ownerActor first.

        // The deployer (this contract) is the initial owner because C.owner is public and not set in constructor; 
        // but given the reference contract as provided, owner is a state variable defaulting to address(0).
        // To ensure there is a meaningful owner that can call transferOwnership, we first set owner to ownerActor by
        // performing transferOwnership from the current owner (this test contract). Since c was deployed by this test
        // contract, the owner is the test contract (address(this)) only if the original contract sets it; if not, we
        // use a pragmatic approach: attempt to set owner to ownerActor by calling transferOwnership as address(this).

        // Ensure this contract has the rights to call transferOwnership: if c.requires onlyOwner and owner is unset (0),
        // the onlyOwner will block. To handle both possibilities, we try to set owner to ownerActor using a try/catch;
        // if it reverts, we skip the scenario since the universal property is about behavior when the caller is the owner.

        bool ok;
        // First, make this contract the owner if possible by transferring from address(this) to ownerActor.
        try c.transferOwnership(ownerActor) {
            // success: now ownerActor is owner
            ok = true;
        } catch {
            // failed: possibly address(this) was not owner; in that case we cannot set up ownerActor as owner
            // So we abort this test input by assuming false to discard this fuzz input (keeps domain wide)
            vm.assume(false);
        }

        // Now impersonate ownerActor and call transferOwnership(ownerActor2) where ownerActor2 is newOwner
        vm.prank(ownerActor);
        c.transferOwnership(newOwner);

        // Single assertion: after a call to transferOwnership by the current owner, the public owner() equals newOwner.
        // This is the universal property the reference satisfies for all inputs; the mutant that omits the assignment will fail
        // for cases where newOwner != previous owner.
        assertTrue(c.owner() == newOwner);
    }
}

