pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller who will act as the owner caller, and the candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Domain restrictions: the contract's initial owner is address(this) because C.owner is default 0x0
        // However, to ensure a meaningful owner we will set the owner to 'caller' by performing
        // an ownership transfer from the deploying address (address(this)). The deployer is not necessarily the owner
        // in the provided C: owner is default zero; to make a consistent admissible domain, require caller != address(0)
        // and newOwner != address(0) to avoid zero-address edge-cases. Keep wide though.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // The test strategy:
        // 1) First, ensure address(this) is the owner by trying to transferOwnership to caller via address(this).
        //    address(this) is the test contract which created c, but initial owner may be zero; transferOwnership is gated by onlyOwner
        //    So we need to set the owner to address(this) if possible. If c.owner() is already address(this) we proceed.
        //    If c.owner() is address(0), we cannot call transferOwnership because onlyOwner will fail. To keep the admissible domain
        //    (so reference holds for all inputs), we instead require that the deployer/test contract is the owner initially.
        //    We therefore assume c.owner() == address(this). This keeps domain wide while ensuring the fuzzed caller can act as current owner
        vm.assume(c.owner() == address(this));

        // 2) Now, impersonate the current owner (address(this)) to transfer ownership to the fuzzed caller.
        //    This makes 'caller' the contract owner so that the decisive call originates from the owner EOA.
        c.transferOwnership(caller);

        // Verify that the transfer succeeded on the reference; must hold for all admissible inputs
        assertTrue(c.owner() == caller);

        // 3) Now, have the fuzzed caller (which is now owner) call transferOwnership(newOwner).
        //    This is the operation that the mutant breaks (it omits assignment).
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // Exactly one assertion about c: after a legitimate owner-initiated transfer, owner == newOwner.
        // The reference C satisfies this for all admissible inputs; the mutant that removed the assignment will fail
        // for some inputs (when caller was owner and newOwner != previous owner).
        assertTrue(c.owner() == newOwner);
    }
}

