    function testFuzz_property(address newOwner) public {
        // Keep domain wide but rule out the trivial case where newOwner is the current owner
        address initialOwner = c.owner();
        vm.assume(newOwner != initialOwner);

        // Act: have the initial owner call transferOwnership(newOwner)
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // Assert: after a legitimate transferOwnership call by the owner, the public getter owner() equals newOwner
