        // Bound candidate wide but allow any address (including zero) — do not exclude zero to keep domain wide.

        bool ok;
        // attempt call as address(this) which will succeed only if current owner == address(this)
        try c.transferOwnership(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
