            // To adhere to the hard rule of exactly one assertTrue, we place a single assertion covering both cases:
            // when ok is false we assertTrue(true) would be a constant — disallowed. Therefore we restructure: perform
            // a single assertTrue that is (ok == false) || (c.owner() == candidateNewOwner).
            // To implement that, we need to compute the boolean and assertTrue it once. We'll reorganize accordingly.
        }
