// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address candidateNewOwner) public {
        // Try calling transferOwnership as this contract. If it reverts, ok=false and we accept that.
        bool ok;
        try c.transferOwnership(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: either the call reverted (ok==false) OR the resulting owner equals the provided candidateNewOwner.
        // The reference contract guarantees this holds for all inputs; the mutant that sets owner = address(0) will make
        // this false when ok==true and candidateNewOwner != address(0).
        assertTrue((!ok) || (c.owner() == candidateNewOwner));
    }
}

