pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: the current owner (caller) and the newOwner candidate
    function testFuzz_property(address initialOwner, address newOwner) public {
        // keep addresses wide but avoid zero address for clarity (still admissible in general)
        vm.assume(initialOwner != address(0));
        vm.assume(newOwner != address(0));

        // Make initialOwner the owner in the deployed contract: the contract's owner is public but uninitialized.
        // We need to set owner to initialOwner by calling transferOwnership from the current owner.
        // On deployment, owner is zero. To set it to initialOwner, we must make the contract's owner equal to msg.sender
        // using transferOwnership; but onlyOwner modifier prevents non-owner calls. So first, we set owner by
        // directly initializing state via calling transferOwnership as the zero owner: since owner starts as zero,
        // we treat address(0) as the initial owner and perform the first call from address(0).
        // However, vm.prank cannot set msg.sender to address(0). Instead, we can handle this by using the
        // fact that owner is public and initially address(0): onlyOwner requires msg.sender == owner, so no one
        // can call transferOwnership until owner is set. Therefore, to make the contract adopt initialOwner,
        // we directly set up the contract by deploying a helper that is the owner via performing the first
        // transferOwnership from address(this) only if the contract's owner is address(this). To achieve a reliable
        // setup that works for the reference contract across all inputs, we instead perform the canonical approach:
        // We first set contract owner to address(this) by deploying a fresh C and then calling transferOwnership
        // from the contract's deployer (address(this) is the deployer here), but since setUp deployed c from this
        // test contract, the deployer of c is this test contract. Thus the initial owner is this test contract.
        // So we will use the test contract (this) as the current owner to change ownership to initialOwner, then
        // later impersonate initialOwner to call transferOwnership(newOwner).

        // Sanity: the test contract deployed c in setUp(), so the owner is address(this). Confirm by reading c.owner().
        address contractOwner = c.owner();
        assert(contractOwner == address(this));

        // step 1: from this test contract (current owner), set owner to initialOwner
        c.transferOwnership(initialOwner);
        // verify the reference should now have owner == initialOwner
        assert(c.owner() == initialOwner);

        // step 2: now impersonate initialOwner and call transferOwnership(newOwner)
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // EXACTLY ONE ASSERT: For the correct contract, after the owner (initialOwner) calls transferOwnership(newOwner),
        // the stored owner must equal the supplied newOwner. The mutant that assigns owner = msg.sender will leave
        // owner == initialOwner instead, so this assertion will fail on that mutant for many fuzzed inputs.
        assertTrue(c.owner() == newOwner);
    }
}

